function M.rows(kind)return kind=='stop'and M.stop or M.detention end
function M.choices(kind)local out={};for _,r in ipairs(M.rows(kind))do out[#out+1]={r.id,r.title}end;return out end
function M.find(kind,id)for _,r in ipairs(M.rows(kind))do if r.id==id then return r end end end
function M.ground(kind,id,branch,custom)
 local r=M.find(kind,id);if not r or id=='none'then return nil,'Сначала выберите '..(kind=='stop'and'причину остановки.'or'основание задержания.')end
 local label=r.title;local part=''
 if id=='custom'then
  if type(custom)~='string'or not core.validUtf8(custom)or #custom>2000 or custom:find('%c')or not custom:match('%S')then return nil,'Заполните своё основание одной строкой.'end
  label=custom
 elseif r.branches then
  local found;for i,b in ipairs(r.branches)do if b[1]==branch then label=label..' · '..b[2];part=tostring(i);found=true;break end end
  if not found then return nil,'Выберите ветвь статьи. PA не определяет её по догадке.'end
 end
 return {id=r.id,title=label,basis=label,article=r.article or'',part=part,game=r.game,note=r.note,kind=kind}
end
